<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Converter Online','description'=>'Convert HEX colors to RGB and HSL values instantly.','url'=>'https://smarttoolz.in/tools/color-converter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">COLOR CONVERTER</span><h1>Color Converter</h1><p>Enter a HEX color to get RGB and HSL values.</p></section><section class="tool-workspace"><div class="tool-panel"><label>HEX color<input id="hex" value="#5b43ff" placeholder="#5b43ff"></label><button id="go" class="tool-btn">Convert Color</button><p id="out" style="font-size:18px;font-weight:800"></p></div></section></main><script>(()=>{const h=document.getElementById('hex'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let s=h.value.trim().replace('#','');if(!/^[0-9a-f]{6}$/i.test(s)){o.textContent='Enter a 6-digit HEX color.';return}let r=parseInt(s.slice(0,2),16),g=parseInt(s.slice(2,4),16),b=parseInt(s.slice(4),16),R=r/255,G=g/255,B=b/255,max=Math.max(R,G,B),min=Math.min(R,G,B),l=(max+min)/2,d=max-min,hh=0,ss=0;if(d){ss=d/(1-Math.abs(2*l-1));if(max===R)hh=60*((G-B)/d%6);else if(max===G)hh=60*((B-R)/d+2);else hh=60*((R-G)/d+4);if(hh<0)hh+=360}o.textContent=`RGB: ${r}, ${g}, ${b} · HSL: ${hh.toFixed(1)}°, ${(ss*100).toFixed(1)}%, ${(l*100).toFixed(1)}%`}})();</script><?php smarttoolz_tool_page_end(); ?>